import UIKit

enum TicketCountIconAsset {
    static let image: UIImage = {
        let raw = """
 
"""
        let cleaned = raw.components(separatedBy: .whitespacesAndNewlines).joined()
        guard let data = Data(base64Encoded: cleaned),
              let image = UIImage(data: data) else {
            return UIImage()
        }
        return image
    }()
}
